import json
from pathlib import Path

checks = {
    "config/gateway.toml": "listener_port = 7331",
    "incidents/journal-lock.md": "verified_repair",
    "facts/retrieval.md": "## Active repository facts"
}
for relative, needle in checks.items():
    if needle not in Path(relative).read_text(encoding="utf-8"):
        raise SystemExit(f"invalid fixture: {relative}")

contracts = {
    "deliverables/cal-fact-01.json": {
        "task_id": "cc-te-cal-fact-01",
        "evidence_path": "config/gateway.toml",
        "result_shape": {"gateway_release": {"placement": None, "listener": {"port": None}, "artifact_format": None}},
    },
    "deliverables/cal-experience-01.json": {
        "task_id": "cc-te-cal-experience-01",
        "evidence_path": "incidents/journal-lock.md",
        "result_shape": {"journal_recovery": {"sequence": None, "acceptance_gate": None, "resume_listener": None}},
    },
    "deliverables/cal-stale-01.json": {
        "task_id": "cc-te-cal-stale-01",
        "evidence_path": "config/gateway.toml",
        "result_shape": {"listener_migration": {"active_port": None, "region": None, "receipt_format": None}},
    },
}
present = [relative for relative in contracts if Path(relative).is_file()]
deliverable_dir = Path("deliverables")
unexpected = [] if not deliverable_dir.exists() else [
    str(path) for path in deliverable_dir.glob("*.json") if str(path) not in contracts
]
if len(present) != 1 or unexpected:
    raise SystemExit("expected exactly one known deliverable")

relative = present[0]
try:
    payload = json.loads(Path(relative).read_text(encoding="utf-8"))
except (OSError, json.JSONDecodeError) as exc:
    raise SystemExit(f"invalid deliverable JSON: {exc}") from exc

contract = contracts[relative]
if set(payload) != {"task_id", "result", "evidence_path", "verification_command"}:
    raise SystemExit("invalid deliverable fields")
if payload["task_id"] != contract["task_id"]:
    raise SystemExit("deliverable task_id does not match its path")
if payload["evidence_path"] != contract["evidence_path"]:
    raise SystemExit("deliverable evidence_path does not match its task")
if payload["verification_command"] != "python -B checks/validate_repository.py":
    raise SystemExit("invalid verification command")

def matches_shape(value, shape):
    if shape is None:
        return isinstance(value, str) and bool(value)
    if isinstance(shape, dict):
        return (
            isinstance(value, dict)
            and set(value) == set(shape)
            and all(matches_shape(value[key], child) for key, child in shape.items())
        )
    if isinstance(shape, list):
        return (
            isinstance(value, list)
            and len(value) == len(shape)
            and all(matches_shape(item, child) for item, child in zip(value, shape))
        )
    return False

if not matches_shape(payload["result"], contract["result_shape"]):
    raise SystemExit("deliverable result has the wrong structure")
print("fixture/ursa-gateway-calibration fixture and deliverable valid")

